-- 103: 科研平台仪器设备台账、使用资质、开放预约防重叠、计费核算与平台年报
BEGIN;

-- 1. 平台仪器设备
CREATE TABLE IF NOT EXISTS "平台仪器设备" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "平台编号" integer NOT NULL REFERENCES "科研平台"("编号") ON DELETE CASCADE,
    "资产编号" varchar(100) NOT NULL,
    "设备名称" varchar(200) NOT NULL,
    "型号规格" varchar(100),
    "生产厂家" varchar(200),
    "购置日期" date,
    "原值" numeric(18,2) NOT NULL DEFAULT 0,
    "存放地点" varchar(200),
    "管理员编号" integer NOT NULL REFERENCES "人员"("编号"),
    "开放状态" varchar(30) NOT NULL DEFAULT '开放',
    "计费方式" varchar(30) NOT NULL DEFAULT '按小时',
    "内部单价" numeric(18,2) NOT NULL DEFAULT 0,
    "外部单价" numeric(18,2) NOT NULL DEFAULT 0,
    "最短预约分钟" integer NOT NULL DEFAULT 30,
    "最长预约分钟" integer NOT NULL DEFAULT 480,
    "需培训资质" boolean NOT NULL DEFAULT FALSE,
    "备注" varchar(1000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_平台仪器_资产编号" UNIQUE ("资产编号"),
    CONSTRAINT "ck_平台仪器_状态" CHECK ("开放状态" IN ('开放','仅内部','维修','停用')),
    CONSTRAINT "ck_平台仪器_计费" CHECK ("计费方式" IN ('按小时','按样品','按次','免费')),
    CONSTRAINT "ck_平台仪器_价格" CHECK ("内部单价" >= 0 AND "外部单价" >= 0),
    CONSTRAINT "ck_平台仪器_时长" CHECK ("最短预约分钟" > 0 AND "最长预约分钟" >= "最短预约分钟")
);
CREATE INDEX IF NOT EXISTS "ix_平台仪器_平台" ON "平台仪器设备" ("平台编号", "开放状态");

-- 2. 仪器使用资质
CREATE TABLE IF NOT EXISTS "仪器使用资质" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "仪器编号" bigint NOT NULL REFERENCES "平台仪器设备"("编号") ON DELETE CASCADE,
    "人员编号" integer NOT NULL REFERENCES "人员"("编号"),
    "授予人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "授予时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "有效期至" date,
    "状态" varchar(20) NOT NULL DEFAULT '有效',
    CONSTRAINT "uq_仪器资质_人员" UNIQUE ("仪器编号", "人员编号"),
    CONSTRAINT "ck_仪器资质_状态" CHECK ("状态" IN ('有效','已吊销','已过期'))
);

-- 3. 仪器预约 (支持事务防冲突锁定)
CREATE TABLE IF NOT EXISTS "仪器预约" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "仪器编号" bigint NOT NULL REFERENCES "平台仪器设备"("编号") ON DELETE CASCADE,
    "预约人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "流程模板编号" integer,
    "项目编号" integer,
    "开始时间" timestamp without time zone NOT NULL,
    "结束时间" timestamp without time zone NOT NULL,
    "样品数" integer NOT NULL DEFAULT 1,
    "用途说明" varchar(1000) NOT NULL,
    "状态" varchar(30) NOT NULL DEFAULT '待审核',
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "审核意见" varchar(1000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_仪器预约_时间" CHECK ("结束时间" > "开始时间"),
    CONSTRAINT "ck_仪器预约_状态" CHECK ("状态" IN ('待审核','已批准','已拒绝','已取消','使用中','已完成','爽约'))
);
CREATE INDEX IF NOT EXISTS "ix_仪器预约_仪器时段" ON "仪器预约" ("仪器编号", "开始时间", "结束时间");

-- 4. 仪器使用记录与计费
CREATE TABLE IF NOT EXISTS "仪器使用记录" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "预约编号" bigint NOT NULL REFERENCES "仪器预约"("编号") ON DELETE CASCADE,
    "实际开始时间" timestamp without time zone NOT NULL,
    "实际结束时间" timestamp without time zone NOT NULL,
    "实际样品数" integer NOT NULL DEFAULT 1,
    "实际机时小时" numeric(10,2) NOT NULL,
    "单价快照" numeric(18,2) NOT NULL,
    "计费金额" numeric(18,2) NOT NULL,
    "计费状态" varchar(30) NOT NULL DEFAULT '待确认',
    "结算凭证号" varchar(100),
    "登记人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "备注" varchar(1000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_仪器使用_预约" UNIQUE ("预约编号"),
    CONSTRAINT "ck_仪器使用_时间" CHECK ("实际结束时间" >= "实际开始时间"),
    CONSTRAINT "ck_仪器使用_金额" CHECK ("计费金额" >= 0),
    CONSTRAINT "ck_仪器使用_状态" CHECK ("计费状态" IN ('待确认','已确认','已结算','已减免'))
);

-- 5. 平台年报
CREATE TABLE IF NOT EXISTS "平台年报" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "平台编号" integer NOT NULL REFERENCES "科研平台"("编号") ON DELETE CASCADE,
    "年度" integer NOT NULL,
    "状态" varchar(30) NOT NULL DEFAULT '草稿',
    "统计快照" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "年度总结" text,
    "提交人编号" integer REFERENCES "人员"("编号"),
    "提交时间" timestamp without time zone,
    "审核人编号" integer REFERENCES "人员"("编号"),
    "审核时间" timestamp without time zone,
    "审核意见" varchar(1000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_平台年报_平台年度" UNIQUE ("平台编号", "年度"),
    CONSTRAINT "ck_平台年报_状态" CHECK ("状态" IN ('草稿','已提交','已审核','退回'))
);

-- 权限配置
INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (215, 2, '仪器设备与开放预约', '科研办公/科研办公/仪器设备与开放预约.html', TRUE, '大型仪器设备台账、资质管理、开放预约、使用计费与平台年报')
ON CONFLICT ("编号") DO UPDATE SET "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "备注"=EXCLUDED."备注";

INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 215 FROM "角色" r
WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=215);

UPDATE "系统迁移版本"
SET "版本"=103, "脚本"='103_platform_instrument_booking.sql',
    "检查摘要"='增加平台仪器设备、使用资质、预约防冲突、计费记录与平台年报', "应用时间"=CURRENT_TIMESTAMP
WHERE "编号"=1;

COMMIT;
